use serde_json::json;use sha2::{Digest,Sha256};use std::{alloc::{GlobalAlloc,Layout},sync::atomic::{AtomicUsize,Ordering::Relaxed},time::Instant,hint::black_box};
use zopro_core::{CallerG1,CallerG2,fft::CallerFft};
static ALLOCS:AtomicUsize=AtomicUsize::new(0);struct Counted;unsafe impl GlobalAlloc for Counted{unsafe fn alloc(&self,l:Layout)->*mut u8{ALLOCS.fetch_add(1,Relaxed);unsafe{zopro_core::alloc::Allocator.alloc(l)}}unsafe fn alloc_zeroed(&self,l:Layout)->*mut u8{ALLOCS.fetch_add(1,Relaxed);unsafe{zopro_core::alloc::Allocator.alloc_zeroed(l)}}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{ALLOCS.fetch_add(1,Relaxed);unsafe{zopro_core::alloc::Allocator.realloc(p,l,n)}}unsafe fn dealloc(&self,p:*mut u8,l:Layout){unsafe{zopro_core::alloc::Allocator.dealloc(p,l)}}}#[global_allocator]static A:Counted=Counted;
enum Fixture{G1(CallerG1),G2(CallerG2),Fft(CallerFft)}
impl Fixture{fn reset(&mut self){match self{Self::G1(f)=>f.reset(),Self::G2(f)=>f.reset(),Self::Fft(f)=>f.reset()}}fn run(&mut self,n:usize){match self{Self::G1(f)=>f.run(n),Self::G2(f)=>f.run(n),Self::Fft(f)=>f.run(n)}}fn check(&self,n:usize){match self{Self::G1(f)=>f.check(n),Self::G2(f)=>f.check(n),Self::Fft(f)=>f.check(n)}}fn bytes(&self)->Vec<u8>{match self{Self::G1(f)=>f.bytes(),Self::G2(f)=>f.bytes(),Self::Fft(f)=>f.bytes()}}fn capacity(&self)->usize{match self{Self::G1(f)=>f.capacity_bytes(),Self::G2(f)=>f.capacity_bytes(),Self::Fft(f)=>f.capacity_bytes()}}}
fn main(){let args:Vec<_>=std::env::args().collect();assert_eq!(args.len(),4);let kind=&args[1];let size:usize=args[2].parse().unwrap();let n:usize=args[3].parse().unwrap();assert!(n>0);rayon::ThreadPoolBuilder::new().num_threads(1).build_global().unwrap();let mut f=match kind.as_str(){"g1"=>Fixture::G1(CallerG1::new(size,false,17)),"g1-signed"=>Fixture::G1(CallerG1::new(size,true,17)),"g2"=>Fixture::G2(CallerG2::new(size,17)),"fft"=>Fixture::Fft(CallerFft::new(size)),_=>panic!("kind")};for _ in 0..3{f.reset();black_box(&mut f).run(8);f.check(8);}f.reset();let before=ALLOCS.load(Relaxed);let start=Instant::now();black_box(&mut f).run(n);let elapsed=start.elapsed();black_box(&f);let allocations=ALLOCS.load(Relaxed)-before;assert_eq!(allocations,0);f.check(n);let bytes=f.bytes();println!("RESULT {}",json!({"kind":kind,"size":size,"iterations":n,"prime_calls":3,"prime_iterations":8,"elapsed_ns":elapsed.as_nanos(),"ns_per_round":elapsed.as_nanos()as f64/n as f64,"timed_allocations":allocations,"capacity_bytes":f.capacity(),"output_sha256":format!("{:x}",Sha256::digest(bytes)),"internally_verified":true,"SDK_requests":0}));}
